mapper.insert:
INSERT INTO roomboards_bookmarks (members_username, roomboards_id)
SELECT #{username}, #{roomboardsId}
WHERE NOT EXISTS (
SELECT 1
FROM roomboards_bookmarks b
WHERE b.members_username = #{username}
AND b.roomboards_id = #{roomboardsId}
);

mapper.select:
SELECT rb.id AS id, rb.members_username AS members_username, rb.title AS title, rb.detail AS detail, rb.address AS address, rb.postcode AS postcode, rb.price AS price, rb.house_size AS house_size, rb.price_per AS price_per, rb.rent_start AS rent_start, rb.rent_until AS rent_until, rb.hashtags AS hashtags, rb.views AS views, rb.created_at AS created_at, rb.updated_at AS updated_at, rbi.url AS thumbnail_url, m.nickname AS nickname, m.profile_image_path AS profileImagePath FROM roomboards_bookmarks b JOIN roomboards rb ON b.roomboards_id = rb.id LEFT JOIN roomboards_images rbi ON rb.id = rbi.roomboards_id AND rbi.image_order = 0 LEFT JOIN members m ON rb.members_username = m.username WHERE b.members_username = #{username}
AND rb.id < #{cursorId}
ORDER BY rb.id DESC LIMIT #{pageSize};

mapper.delete:
DELETE FROM housedeals_bookmarks
WHERE members_username = #{username}
AND housedeals_no = #{housedealsNo};

mapper.select:
SELECT b.id AS bookmarkId, b.housedeals_no AS dealNo, h.apt_seq AS aptSeq, h.deal_amount AS dealAmount, c.apt_name AS aptName, c.latitude AS latitude, c.longitude AS longitude, b.created_at AS bookmarkedAt, -- 추가 필드 c.sido_name AS sidoName, c.gugun_name AS gugunName, c.dong_name AS dongName, c.jibun AS jibun, c.build_year AS buildYear, h.exclu_use_ar AS excluUseAr, h.floor AS floor, CASE WHEN h.apt_dong = ' ' THEN NULL ELSE h.apt_dong END AS aptDong, h.deal_year AS dealYear, h.deal_month AS dealMonth, h.deal_day AS dealDay FROM housedeals_bookmarks b JOIN housedeals h ON b.housedeals_no = h.no JOIN housecards c ON h.apt_seq = c.apt_seq WHERE b.members_username = #{username}
AND b.id < #{cursorId}
ORDER BY b.id DESC LIMIT #{pageSize};
